#Requires -Version 5.1
# fix-planificador-vista-personas-error.ps1
#
# IMPLEMENTACION:
#
# 1. src/app/planificacion/page.tsx (MODIFICADO)
#    Causa raiz del "Application error" al entrar en Vista Personas:
#      SortablePersonRow referenciaba una variable "obra" inexistente en su
#      scope (copiada de ObraRow al anadir el resaltado de celda durante
#      drag & drop), y no recibia "activeOver" como prop -> ReferenceError
#      en cada render de fila de persona.
#    Cambios:
#      - SortablePersonRow ahora recibe activeOver como prop y compara
#        contra persona.id (no contra "obra", que no existe en ese scope).
#      - Fallbacks seguros: persona?.id, persona?.nombre, filtrado de
#        personas sin id antes de renderizar, obras || [].
#      - Nuevo useEffect: limpia activeDrag/activeOver al cambiar planView,
#        para no arrastrar ids de la vista anterior a la nueva.
#      - Vista Obras y Vista Personas envueltas cada una en su propio
#        PlanificadorErrorBoundary (aislamiento de fallos entre vistas).
#
# 2. src/app/planificacion/PlanificadorErrorBoundary.tsx (NUEVO)
#    ErrorBoundary de React siguiendo el patron ya existente de
#    GeoradarErrorBoundary. A diferencia de un try/catch vacio:
#      - Muestra el error real al usuario (no lo oculta).
#      - Permite reintentar sin recargar toda la app.
#      - Registra el fallo en audit_log via logAuditErrorClient (sistema
#        ya existente), modulo "planificacion", entidad "asignaciones".
#
# AUDIT LOG: no se anaden tablas ni endpoints. Se anade cobertura de
# auditoria para errores de render del Planificador reutilizando el
# sistema audit_log existente (logAuditErrorClient / /api/audit/log-error).
#
# EJECUCION: no requiere migracion SQL ni pasos manuales en Supabase.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR: no se encuentra $RepoPath" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> fix: Vista Personas del planificador (ReferenceError + audit_log)" -ForegroundColor Cyan

Write-Host "  -> src\app\planificacion\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\planificacion\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\page.tsx"), $bytes)
Write-Host "  OK: 76 KB" -ForegroundColor Green

Write-Host "  -> src\app\planificacion\PlanificadorErrorBoundary.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\planificacion\PlanificadorErrorBoundary.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\planificacion\PlanificadorErrorBoundary.tsx"), $bytes)
Write-Host "  OK: 3 KB" -ForegroundColor Green

$page = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\page.tsx"), [System.Text.Encoding]::UTF8)
$boundary = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\planificacion\PlanificadorErrorBoundary.tsx"), [System.Text.Encoding]::UTF8)
if ($page.Contains("activeOver?.obraId === persona.id"))         { Write-Host "  OK: fix ReferenceError (persona.id, no obra.id)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains("PlanificadorErrorBoundary"))                 { Write-Host "  OK: ErrorBoundary integrado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains("setActiveDrag(null); setActiveOver(null); }, [planView]"))  { Write-Host "  OK: limpieza de drag & drop al cambiar de vista" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($boundary.Contains("logAuditErrorClient"))                   { Write-Host "  OK: registro en audit_log" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }

Write-Host ""
Write-Host "  No requiere migracion SQL ni pasos manuales en Supabase." -ForegroundColor Yellow
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "fix: ReferenceError en Vista Personas del planificador (obra->persona) + ErrorBoundary con audit_log"'
Write-Host "  git push"
Write-Host ""
Write-Host "  Despues del deploy: Vercel -> Deployments -> ... -> Promote to Production" -ForegroundColor Yellow
